    "app.engineTuning.contextCompactionHelp": "Dotyczy każdego mechanizmu. Próg podsumowywania ustawiony dla modelu w sekcji Modele -\u003e Dostrajanie ma pierwszeństwo przed tym współczynnikiem globalnym.",
    "app.engineTuning.delegationHelp": "Rozdzielanie pracy między agentów pomocniczych. Wywołania narzędzi w ramach jednej tury są zawsze wykonywane kolejno; tylko delegowanie pozwala Jenny pracować równolegle.",
    "app.engineTuning.maxBudgetUsdHelp": "Zatrzymaj odpowiedź, gdy koszt dostawcy w tej turze przekroczy podaną kwotę. Pozostaw puste pole, aby nie ustawiać limitu.",
    "app.engineTuning.maxChatLoopIterationsHelp": "Liczba ponownych etapów namysłu Jenny po użyciu narzędzi podczas zwykłej odpowiedzi na czacie.",
    "app.engineTuning.maxCloudSubAgentConcurrencyHelp": "Liczba zadań pomocniczych wykonywanych równocześnie przez model chmurowy. Harmonogram ogranicza ją do 3.",
    "app.engineTuning.maxCodeIntelligenceToolCallsPerTurnHelp": "Liczba wywołań narzędzi do analizy kodu dostępnych w jednej odpowiedzi.",
    "app.engineTuning.maxInlinePayloadBytesHelp": "Większe wyniki narzędzi są zapisywane do pliku i dołączane jako link, zamiast trafiać bezpośrednio do rozmowy.",
    "app.engineTuning.maxLoopIterationsHelp": "Używane tylko po wyłączeniu oszczędzania zasobów. Określa też początkowy limit czatu, jeśli nie został on ustawiony.",
    "app.engineTuning.maxLoopWallSecondsHelp": "Czas aktywnej pracy lokalnej tury. Oczekiwanie na zatwierdzenie lub odpowiedzi użytkownika nie wlicza się do tego limitu.",
    "app.engineTuning.maxSubAgentConcurrencyHelp": "Liczba zadań pomocniczych wykonywanych równocześnie przez model lokalny. Wartość 1 oznacza wykonywanie po kolei.",
    "app.engineTuning.maxSubAgentLoopIterationsHelp": "Liczba rund rozumowania dostępnych dla każdego zadania pomocniczego. Celowo jest taka sama lokalnie i w chmurze: większe zadanie powinno uruchamiać więcej pomocników, a nie wydłużać ich pracę.",
    "app.engineTuning.maxTaskLoopIterationsHelp": "Taki sam limit dla trybu zadania, w którym oczekiwana jest dłuższa praca wieloetapowa. Przy wartości domyślnej wolny model lokalny dostaje do czterech razy więcej rund.",
    "app.engineTuning.maxToolCallsPerSessionHelp": "Limit bezpieczeństwa wywołań narzędzi w całej rozmowie, zapobiegający nieskończonemu działaniu zapętlonego procesu.",
    "app.engineTuning.maxToolsPerTurnHelp": "Liczba wywołań narzędzi, takich jak odczyt plików czy wyszukiwanie w sieci, których Jenny może użyć podczas odpowiadania na jedną wiadomość. Zwiększ ją przy długich zadaniach intensywnie korzystających z narzędzi albo zmniejsz, aby przyspieszyć odpowiedzi.",
    "app.engineTuning.maxWebToolCallsPerTurnHelp": "Liczba wyszukiwań w sieci lub pobrań stron dostępnych w jednej odpowiedzi. Liczą się tylko udane wywołania; nieudane nie pomniejszają limitu.",
    "app.engineTuning.modelLoadGraceSecondsHelp": "Czas oczekiwania na pierwsze słowa, gdy model lokalny jest jeszcze ładowany do pamięci procesora graficznego. Zwiększ go dla bardzo dużych modeli lub wolnych dysków.",
    "app.engineTuning.ollamaRequestTimeoutSecondsHelp": "Maksymalny czas pojedynczego żądania do Ollama przed jego przerwaniem.",
    "app.engineTuning.reasoningHelp": "Każda runda obejmuje jedno wygenerowanie odpowiedzi przez model i żądane przez niego wywołania narzędzi. Zwiększenie tych limitów pozwala dłużej pracować nad turą przed jej przerwaniem.",
    "app.engineTuning.spendHelp": "Nieprzekraczalny limit kosztu jednej odpowiedzi u płatnego dostawcy.",
    "app.engineTuning.timeoutsHelp": "Czas oczekiwania Jenny przed rezygnacją z narzędzia, ładowania modelu lub żądania.",
    "app.engineTuning.tokenBudgetAutoCompactRatioHelp": "Gdy rozmowa zajmie tę część okna kontekstu modelu, starsze wiadomości zostaną automatycznie podsumowane. Niższa wartość powoduje wcześniejsze podsumowanie.",
    "app.engineTuning.tokenBudgetReservedForSummaryHelp": "Miejsce pozostawione w oknie kontekstu na podsumowanie tworzone podczas kompresji.",
    "app.engineTuning.tokenBudgetToolOverheadHelp": "Dodatkowe miejsce zakładane dla każdego wywołania narzędzia podczas szacowania zapełnienia okna kontekstu.",
