    "diagnostics.issues.explain.engineNotice.cause": "llama.cpp, który uruchamia modele lokalne i indeks wyszukiwania według znaczenia, wypisuje uwagi podczas wczytywania modelu. Zwykle są nieszkodliwe. Sprawdź je tylko wtedy, gdy model się nie wczytuje lub odpowiada dziwnie.",
