    "mcp.servers.readOnlyAutoAllowHelp": "Narzędzia, które ten serwer oznacza jako tylko do odczytu (i ani jako otwarte na świat, ani jako destrukcyjne), pomijają zatwierdzanie każdego wywołania, są automatycznie ponawiane i działają w trybie Plan. Włącz to tylko dla serwera, któremu ufasz, że uczciwie oznacza swoje narzędzia. Zmiana tego ustawienia odsyła połączenie z powrotem do przeglądu: przetestuj je i zatwierdź ponownie. Dopóki jest włączone, to samo dzieje się, gdy serwer później zmieni oznaczenie.",
